Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -20,4 +20,38 @@
 <div class="ending" id="ending"><div class="ending-inner"><div class="eyebrow">SIGNAL RESTORED</div><h2>YOU WERE<br>THE <span class="title-accent">ECHO.</span></h2><p>The voice was yours. A message sent backward through a dying star, carrying the memories of a world you had not yet saved.<br><br>Somewhere in the dark, the signal begins again.</p><button id="againBtn">RETURN TO THE BEGINNING</button></div></div>
 <div class="touch-controls"><div class="touch-group"><button class="touch-btn" data-key="left">◀</button><button class="touch-btn" data-key="right">▶</button></div><div class="touch-group"><button class="touch-btn action" data-key="jump">↑</button><button class="touch-btn action" data-key="attack">✦</button><button class="touch-btn" data-key="dash">»</button></div></div>
 </section><footer class="bottom-bar"><div class="controls"><span><b class="key">A D</b> MOVE</span><span><b class="key">SPACE</b> JUMP</span><span><b class="key">J</b> PULSE</span><span><b class="key">SHIFT</b> DASH</span><span><b class="key">E</b> LISTEN</span></div><div class="objective-foot">A signal is never just a sound.</div></footer></main>
 <script>
+(()=>{
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
+const W=480,H=270,worldW=3020,ground=238;
+const el=id=>document.getElementById(id);
+const platforms=[
+[0,238,405],[454,193,80],[510,238,372],[902,198,92],[1000,238,330],[1345,200,94],[1445,238,365],[1825,191,110],[1945,238,345],[2305,204,95],[2415,238,605],
+[170,190,75],[600,174,88],[744,205,72],[1100,183,82],[1225,154,70],[1545,176,90],[1690,205,80],[2040,180,90],[2185,155,78],[2530,184,80],[2670,160,90]
+];
+const gaps=[[405,454],[494,510],[872,902],[994,1000],[1330,1345],[1810,1825],[2295,2305]];
+const hazards=[{x:295,y:226,w:38,h:12},{x:635,y:226,w:45,h:12},{x:795,y:226,w:34,h:12},{x:1085,y:226,w:40,h:12},{x:1560,y:226,w:48,h:12},{x:1985,y:226,w:40,h:12},{x:2465,y:226,w:48,h:12}];
+const fragments=[{x:330,y:190,got:false,text:'“We did not find life on Orpheus. We found a memory with its eyes open.” — Dr. Sato'},{x:1195,y:145,got:false,text:'“The transmission is coming from beneath the crust. It uses my voice. I have never been here.” — Captain Vale'},{x:2125,y:170,got:false,text:'“If you hear this, you made it back. I am sorry I could not make it out with you.” — Vesper, shipmind'}];
+const terminals=[{x:175,y:214,text:'ARCHIVE // ENTRY 01\nThe colony is gone. Their shelters remain warm, as if the planet is holding its breath.'},{x:1015,y:214,text:'ARCHIVE // ENTRY 07\nShipmind Vesper was built from the captain’s neural map. The two voices were never separate.'},{x:1940,y:214,text:'ARCHIVE // ENTRY 13\nOrpheus is not a planet. It is a lighthouse—built from the memory of everyone it has ever saved.'}];
+let player={x:45,y:200,vx:0,vy:0,w:12,h:20,face:1,hp:5,maxHp:5,energy:100,onGround:false,invuln:0,dash:0,dashCD:0,attackCD:0,checkpoint:45,respawnY:200};
+let enemies=[{x:280,y:218,base:280,min:250,max:365,hp:2,kind:'crawler',alive:true},{x:715,y:218,base:715,min:690,max:820,hp:2,kind:'crawler',alive:true},{x:1140,y:218,base:1140,min:1050,max:1290,hp:3,kind:'stalker',alive:true},{x:1615,y:218,base:1615,min:1500,max:1760,hp:2,kind:'crawler',alive:true},{x:2050,y:218,base:2050,min:1980,max:2240,hp:3,kind:'stalker',alive:true},{x:2540,y:218,base:2540,min:2435,max:2600,hp:3,kind:'crawler',alive:true}];
+let boss={x:2780,y:192,w:27,h:42,hp:8,max:8,alive:true,fire:70,phase:0};
+let shots=[],foeShots=[],particles=[],keys={},cam=0,started=false,paused=false,dead=false,complete=false,clock=0,frags=0,terminalSeen={},messageTimer=0,checkpointAt=0;
+let audio=null,soundOn=false;
+function beep(freq=360,dur=.07,type='sine',vol=.025){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.value=vol;o.connect(g);g.connect(audio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.stop(audio.currentTime+dur)}catch(e){}}
+function announce(text,time=2200){const box=el('message');box.textContent=text;box.classList.add('show');messageTimer=time}
+function updateHUD(){el('health').innerHTML='';for(let i=0;i<player.maxHp;i++){const p=document.createElement('i');p.className='pip'+(i>=player.hp?' empty':'');el('health').appendChild(p)}el('energyFill').style.width=player.energy+'%';el('energyText').textContent=Math.floor(player.energy);el('fragments').textContent='◇ '+frags+' / 3';el('sector').textContent=player.x<900?'THE HUSHING RIM':player.x<1800?'THE GLASS TRENCH':player.x<2500?'THE PALE ARCHIVE':'THE HEART BELOW';el('objective').textContent=player.x<2600?'Reach the signal source':boss.alive?'Silence the Warden':'Enter the signal'}
+function start(){started=true;el('intro').classList.add('hidden');announce('ORPHEUS // ATMOSPHERE BREATHABLE. THAT IS NOT POSSIBLE.',3100);beep(520,.15,'triangle')}
+el('startBtn').addEventListener('click',start);
+el('soundBtn').addEventListener('click',()=>{soundOn=!soundOn;el('soundBtn').textContent=soundOn?'♫':'♪';if(soundOn)beep(660)});
+el('resumeBtn').addEventListener('click',()=>{paused=false;el('pause').classList.remove('show')});
+function reset(){player={x:player.checkpoint,y:player.respawnY,vx:0,vy:0,w:12,h:20,face:1,hp:5,maxHp:5,energy:100,onGround:false,invuln:100,dash:0,dashCD:0,attackCD:0,checkpoint:player.checkpoint,respawnY:player.respawnY};shots=[];foeShots=[];dead=false;el('gameOver').classList.remove('show');updateHUD()}
+el('retryBtn').addEventListener('click',reset);
+el('againBtn').addEventListener('click',()=>{location.reload()});
+function keyDown(e){let k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup'].includes(k))e.preventDefault();if(k==='escape'||k==='p'){if(started&&!complete&&!dead){paused=!paused;el('pause').classList.toggle('show',paused)}return}keys[k]=true;if(!started&&k==='enter')start();if(k==='e')interact();if(k==='j'||k==='x')attack();if((k===' '||k==='arrowup'||k==='w')&&!e.repeat)jump();if(k==='shift'&&!e.repeat)dash()}
+function keyUp(e){keys[e.key.toLowerCase()]=false}
+window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);
+function jump(){if(!started||paused||dead||complete)return;if(player.onGround){player.vy=-6.5;player.onGround=false;beep(240,.06,'square',.012)}else if(player.energy>=25){player.vy=-6.1;player.energy-=25;beep(400,.08,'triangle',.015)}}
+function dash(){if(!started||paused||dead||player.dashCD>0||player.energy<20)return;player.energy-=20;player.dash=10;player.dashCD=48;player.vy=0;player.vx=player.face*6.8;beep(170,.12,'sawtooth',.012);for(let i=0;i<5;i++)particles.push({x:player.x+6,y:player.y+10,vx:-player.face*Math.random()*2,vy:(Math.random()-.5),life:16,color:'#6cf5ed'})}
+function attack(){if(!started||paused||dead||player.attackCD>0||player.energy<8)return;player.energy-=8;player.attackCD=20;shots.push({x:player.x+(player.face>0?player.w:0),y:player.y+9,vx:player.face*5.2,life:66});beep(580,.09,'square',.018)}
+function interact(){if(!started||paused)return;let nearest=null,dist=38;for(const t of terminals){let d=Math.hypot(player.x+6-t.x,player.y+10-t.y);if(d<dist){dist=d;nearest=t}}if(nearest){announce(nearest.text.replace('\n','  ·  '),4700);beep(710,.18,'sine');return}for(const f of fragments){if(!f.got&&Math.hypot(player.x+6-f.x,player.y+10-f.y)<38){f.got=true;frags++;player.energy=100;announce(f.text,5000);beep(820,.3,'triangle');updateHUD();return}}if(Math.abs(player.x-2280)<45){player.checkpoint=2240;player.respawnY=200;if(checkpointAt!==2240){checkpointAt=2240;announce('CHECKPOINT // MEMORY ANCHOR SYNCHRONIZED',2500);player.hp=player.maxHp;beep(480,.25,'sine')}}}

input.newString:
function interact(){if(!started||paused)return;let nearest=null,dist=38;for(const t of terminals){let d=Math.hypot(player.x+6-t.x,player.y+10-t.y);if(d<dist){dist=d;nearest=t}}if(nearest){announce(nearest.text.replace('\n','  ·  '),4700);beep(710,.18,'sine');return}for(const f of fragments){if(!f.got&&Math.hypot(player.x+6-f.x,player.y+10-f.y)<38){f.got=true;frags++;player.energy=100;announce(f.text,5000);beep(820,.3,'triangle');updateHUD();return}}if(Math.abs(player.x-2280)<45){player.checkpoint=2240;player.respawnY=200;if(checkpointAt!==2240){checkpointAt=2240;announce('CHECKPOINT // MEMORY ANCHOR SYNCHRONIZED',2500);player.hp=player.maxHp;beep(480,.25,'sine')}}}
function overlap(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function hitPlayer(dmg=1){if(player.invuln>0||dead)return;player.hp-=dmg;player.invuln=75;player.vy=-3;player.vx=-player.face*2.7;beep(100,.22,'sawtooth',.04);for(let i=0;i<8;i++)particles.push({x:player.x+6,y:player.y+10,vx:(Math.random()-.5)*3,vy:(Math.random()-.5)*3,life:18,color:'#ff786e'});updateHUD();if(player.hp<=0){dead=true;el('gameOver').classList.add('show')}}
function update(dt){clock+=dt;if(!started||paused||dead||complete)return;const step=dt/16.67;player.invuln=Math.max(0,player.invuln-step);player.dashCD=Math.max(0,player.dashCD-step);player.attackCD=Math.max(0,player.attackCD-step);player.energy=Math.min(100,player.energy+.13*step);
if(player.dash>0){player.dash-=step}else{let dir=(keys.a||keys.arrowleft?-1:0)+(keys.d||keys.arrowright?1:0);if(dir){player.face=dir>0?1:-1;player.vx+=dir*.48*step;player.vx=Math.max(-2.2,Math.min(2.2,player.vx))}else player.vx*=Math.pow(.78,step);player.vy=Math.min(7,player.vy+.31*step)}
let oldY=player.y;player.x+=player.vx*step;player.x=Math.max(0,Math.min(worldW-player.w,player.x));player.y+=player.vy*step;player.onGround=false;
for(const p of platforms){let [px,py,pw]=p;if(player.x+player.w>px&&player.x<px+pw&&oldY+player.h<=py&&player.y+player.h>=py&&player.vy>=0){player.y=py-player.h;player.vy=0;player.onGround=true}}
if(player.y>H+30){hitPlayer(1);player.x=player.checkpoint;player.y=player.respawnY;player.vx=0;player.vy=0}
for(const h of hazards){if(overlap(player,{x:h.x,y:h.y,w:h.w,h:h.h})&&player.dash<=0)hitPlayer()}
for(const e of enemies){if(!e.alive)continue;e.x+=Math.sin(clock*.0015+e.base)*.7*step;if(e.x<e.min)e.x=e.min;if(e.x>e.max)e.x=e.max;if(overlap(player,{x:e.x,y:e.y,w:20,h:18})&&player.dash<=0)hitPlayer()}
for(const s of shots){s.x+=s.vx*step;s.life-=step;for(const e of enemies){if(e.alive&&s.life>0&&Math.abs(s.x-(e.x+10))<14&&Math.abs(s.y-(e.y+9))<14){e.hp--;s.life=0;for(let i=0;i<5;i++)particles.push({x:e.x+10,y:e.y+8,vx:(Math.random()-.5)*2,vy:(Math.random()-.5)*2,life:14,color:'#ff9d87'});if(e.hp<=0){e.alive=false;player.energy=Math.min(100,player.energy+16);beep(190,.1,'square')}}}if(boss.alive&&s.life>0&&Math.abs(s.x-(boss.x+14))<24&&Math.abs(s.y-(boss.y+20))<31){boss.hp--;s.life=0;boss.phase=18;beep(115,.12,'sawtooth');if(boss.hp<=0){boss.alive=false;announce('WARDEN // “I remember you now.”',3400);beep(520,.5,'triangle')}}}shots=shots.filter(s=>s.life>0&&s.x>cam-20&&s.x<cam+W+30);
if(boss.alive){boss.phase=Math.max(0,boss.phase-step);boss.fire-=step;if(boss.fire<=0&&Math.abs(boss.x-player.x)<390){boss.fire=88;foeShots.push({x:boss.x,y:boss.y+20,vx:Math.sign(player.x-boss.x)*2.1,vy:-.3,life:180});beep(145,.06,'square',.01)}}
for(const s of foeShots){s.x+=s.vx*step;s.y+=s.vy*step;s.life-=step;if(overlap(player,{x:s.x-3,y:s.y-3,w:6,h:6})){s.life=0;hitPlayer()}}foeShots=foeShots.filter(s=>s.life>0);
for(const p of particles){p.x+=p.vx*step;p.y+=p.vy*step;p.life-=step}particles=particles.filter(p=>p.life>0);
cam=Math.max(0,Math.min(worldW-W,player.x-W*.38));if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)el('message').classList.remove('show')}
if(player.x>2240&&player.x<2280&&checkpointAt!==2240){player.checkpoint=2240;player.respawnY=200;checkpointAt=2240;player.hp=player.maxHp;announce('CHECKPOINT // MEMORY ANCHOR SYNCHRONIZED',2400)}
if(player.x>2910&&!boss.alive){complete=true;el('ending').classList.add('show');beep(660,.6,'sine')}
updateHUD()}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.floor(x),Math.floor(y),Math.ceil(w),Math.ceil(h))}
function drawBackground(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#091020');g.addColorStop(.7,'#111b2d');g.addColorStop(1,'#18243a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// distant planet
ctx.fillStyle='#182a43';ctx.beginPath();ctx.arc(362-cam*.055,78,59,0,Math.PI*2);ctx.fill();ctx.fillStyle='#203651';ctx.beginPath();ctx.arc(355-cam*.055,69,46,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2d5363';ctx.fillRect(Math.floor(338-cam*.055),41,29,3);ctx.fillRect(Math.floor(367-cam*.055),63,20,4);ctx.fillRect(Math.floor(320-cam*.055),90,38,3);
for(let i=0;i<85;i++){let x=((i*97-cam*(i%3===0?.12:.025))%(W+40)+W+40)%(W+40),y=(i*53+17)%160;let tw=i%11===Math.floor(clock/500)%11;rect(x,y,tw?2:1,tw?2:1,tw?'#a1f5ee':'#627f9b')}
// jagged far skyline
for(let i=0;i<18;i++){let x=((i*81-cam*.22)%(W+100)+W+100)%(W+100)-35;let h=25+(i*29%68);rect(x,198-h,20,h,'#101a2b');rect(x+5,194-h,4,4,'#244553');if(i%3===0)rect(x+12,190-h,2,7,'#466579')}
// horizon glow
let gr=ctx.createLinearGradient(0,175,0,240);gr.addColorStop(0,'#12233300');gr.addColorStop(1,'#23425488');ctx.fillStyle=gr;ctx.fillRect(0,175,W,65)}

